CREATE OR REPLACE FUNCTION public.protect_membership_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN IF NEW.school_id IS DISTINCT FROM OLD.school_id OR NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'Membership identity cannot be changed'; END IF; IF OLD.role::text='head' AND public.member_role(OLD.school_id)::text <> 'head' THEN RAISE EXCEPTION 'Only a School Head can change a School Head membership'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_membership_update BEFORE UPDATE ON public.school_members FOR EACH ROW EXECUTE FUNCTION public.protect_membership_update();
CREATE OR REPLACE FUNCTION public.void_receipt(_receipt uuid, _reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _r payment_receipts; BEGIN SELECT * INTO _r FROM payment_receipts WHERE id=_receipt; IF _r.id IS NULL THEN RAISE EXCEPTION 'Not found'; END IF; IF NOT coalesce(public.member_role(_r.school_id)::text IN ('head','admin','bursar'),false) THEN RAISE EXCEPTION 'Not permitted'; END IF; IF coalesce(trim(_reason),'')='' THEN RAISE EXCEPTION 'Reason required'; END IF; IF _r.voided THEN RAISE EXCEPTION 'Already voided'; END IF; UPDATE payment_receipts SET voided=true, void_reason=_reason, voided_at=now(), voided_by=auth.uid() WHERE id=_receipt; INSERT INTO audit_logs(school_id,user_id,action,record_type,record_id,details) VALUES (_r.school_id,auth.uid(),'receipt.voided','payment_receipt',_receipt,jsonb_build_object('reason',_reason)); END $$;